#ifndef SOUNDDATABASE_H
#define SOUNDDATABASE_H

#include "SoundTypes.h"

#include <QHash>
#include <QString>

namespace Sound
{
    // Name metadata for the supported vanilla ROM. The data is generated by the
    // developer tool and shipped as a Qt resource. The ROM never stores names,
    // so a missing/corrupt database only affects display names; parsing and
    // editing still work with fallback names.
    class SoundDatabase
    {
    public:
        struct SongInfo
        {
            QString name;
            QString description;
        };

        static SoundDatabase &instance();

        // Loads :/SoundData/WL4SoundDatabase.json, or a file next to the
        // executable if the resource is absent. Never fails hard: an empty
        // database simply makes the lookup helpers return the fallback.
        bool load(QString *error = nullptr);
        bool isLoaded() const { return loaded; }

        QString songName(int id, const QString &fallback) const;
        QString songDescription(int id) const;

        QString bankName(int id, const QString &fallback) const;
        QString programName(int bankId, int program, const QString &fallback) const;

        // The key is the ROM address of the sample's 16-byte header.
        QString sampleName(quint32 romAddress, const QString &fallback) const;

    private:
        SoundDatabase() = default;
        SoundDatabase(const SoundDatabase &) = delete;
        SoundDatabase &operator=(const SoundDatabase &) = delete;

        bool loaded = false;
        QHash<int, SongInfo> songs;
        QHash<int, QString> bankNames;
        QHash<int, QHash<int, QString>> programNames;
        QHash<quint32, QString> sampleNames;
    };
} // namespace Sound

#endif // SOUNDDATABASE_H
